{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Batefenterol, a large polar drug, had an absolute oral bioavailability of only 0.012% in healthy male subjects, directly demonstrating that extensive polar functionality and high molecular complexity can produce extremely low oral F; its high transfer score supports a low-F expectation for the similarly large, polar query peptide.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Aliskiren has a measured absolute oral bioavailability of 2.6% in humans, far below the 20% threshold, despite being a smaller drug; this supports the conclusion that the query, with far more polar surface area and peptide character, will also have low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Melagatran has a human oral bioavailability of only 3–7%, providing another high-transfer experimental example of a drug with low systemic availability after oral dosing and supporting a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Tegaserod has an absolute oral bioavailability of approximately 10% in healthy volunteers, still well below the 20% threshold; this reinforces the pattern that even moderately absorbed small molecules in the evidence set do not reach high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C29"],
      "claim": "Linaclotide, a peptide, has low oral bioavailability in humans with activity limited to the gastrointestinal tract; as the closest peptide analogue, it directly supports the expectation that the large peptide query will also have low systemic oral bioavailability.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All retrieved experimental analogues have absolute oral bioavailability well below 20% (0.012–14%), and the query is a large peptide with extensive polar/H-bonding character and fatty-acid/PEG modifications that further limit membrane permeability; therefore low oral bioavailability is strongly supported.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement is available for the query molecule itself.",
    "Most analogues are small molecules; the closest peptide analogue (linaclotide) is reported only qualitatively as low, not with a numeric F value.",
    "Oral absorption of peptide drugs can be formulation-dependent, but the intrinsic oral bioavailability remains low."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

